{
  "test_name": "Case 4: Nested Objects",
  "description": "Validate nested object type preservation through 3 levels of nesting",
  "input": {
    "level1": {
      "int_field": 100,
      "bool_field": false,
      "level2": {
        "float_field": 99.99,
        "string_field": "nested",
        "level3": {
          "deep_int": 777,
          "deep_bool": true
        }
      }
    }
  },
  "expected_output": {
    "level1": {
      "int_field": 100,
      "bool_field": false,
      "level2": {
        "float_field": 99.99,
        "string_field": "nested",
        "level3": {
          "deep_int": 777,
          "deep_bool": true
        }
      }
    }
  },
  "validation_strategy": "field_by_field_comparison",
  "type_check": "type(returned_value) == type(original_value)",
  "value_check": "returned_value == original_value"
}
